from pathlib import Path
import subprocess
root = Path('.').resolve()
native = root / 'native'
main = root / 'native/inir-mpdd/src/main.rs'
before = main.read_text()
r = subprocess.run(['cargo','fmt','--package','inir-mpdd'], cwd=native, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
if r.returncode != 0: raise SystemExit(70)
after = main.read_text()
names = subprocess.run(['git','diff','--name-only'], cwd=root, text=True, capture_output=True, check=True).stdout.splitlines()
target = 'native/inir-mpdd/src/main.rs'
if names != [target]:
    raise SystemExit(71 if target in names else 72)
needle = '                borrowed.expect("serialize borrowed daemon result")\n            );'
if before.count(needle) != 1: raise SystemExit(73)
pred1 = before.replace(needle, '                borrowed.expect("serialize borrowed daemon result"),\n            );', 1)
pred2 = None
for old, new in [('\n    }\n\n}\n','\n    }\n}\n'), ('\n    }\n\n}','\n    }\n}')]:
    if pred1.endswith(old):
        pred2 = pred1[:-len(old)] + new
        break
if after == pred1: raise SystemExit(41)
if pred2 is not None and after == pred2: raise SystemExit(42)
marker = '    #[test]\n    fn daemon_result_borrow_serialization_matches_owned_clone()'
bpre, bsep, _ = before.partition(marker)
apre, asep, _ = after.partition(marker)
if bsep and asep and bpre == apre and 'borrowed.expect("serialize borrowed daemon result"),' in after:
    raise SystemExit(45)
if bsep and asep and bpre != apre: raise SystemExit(46)
raise SystemExit(47)
